function PS4Buttons.OnAddOnLoaded(event, addonName)
    if addonName ~= PS4Buttons.name then return end
    
    PS4Buttons:Initialize()
end

EVENT_MANAGER:RegisterForEvent(PS4Buttons.name, EVENT_ADD_ON_LOADED, PS4Buttons.OnAddOnLoaded)